insert into public.permissions(code,module,description) values
 ('social_teams.read','social_inbox','Сошиал баг, Page хуваарилалт харах'),('social_teams.manage','social_inbox','Сошиал баг, Page хуваарилалт удирдах'),('social_inbox.reassign','social_inbox','Харилцааг өөр ажилтанд шилжүүлэх'),('social_analytics.read','social_inbox','Page, баг, ажилтны үзүүлэлт харах')
on conflict(code) do update set module=excluded.module,description=excluded.description;

alter table public.facebook_pages add column if not exists credential_reference text, add column if not exists connection_status text not null default 'disconnected' check(connection_status in('disconnected','pending','connected','error')), add column if not exists settings jsonb not null default '{}'::jsonb;
create unique index if not exists facebook_pages_external_org_unique on public.facebook_pages(organization_id,external_page_id) where external_page_id is not null;

create table public.social_teams(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,leader_id uuid references public.profiles(id) on delete set null,is_active boolean not null default true,page_capacity integer check(page_capacity is null or page_capacity>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,name));
create table public.social_team_members(team_id uuid not null references public.social_teams(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,is_active boolean not null default true,joined_at timestamptz not null default now(),primary key(team_id,user_id));
create table public.social_page_teams(page_id uuid not null references public.facebook_pages(id) on delete cascade,team_id uuid not null references public.social_teams(id) on delete cascade,assignment_type text not null check(assignment_type in('primary','backup')),priority smallint not null default 1 check(priority>0),created_at timestamptz not null default now(),primary key(page_id,team_id,assignment_type));
create unique index social_page_primary_team on public.social_page_teams(page_id) where assignment_type='primary';
create table public.social_page_user_access(page_id uuid not null references public.facebook_pages(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,can_read boolean not null default true,can_reply boolean not null default false,can_assign boolean not null default false,created_at timestamptz not null default now(),primary key(page_id,user_id));
create table public.social_agent_presence(user_id uuid primary key references public.profiles(id) on delete cascade,organization_id uuid not null references public.organizations(id) on delete cascade,status text not null default 'offline' check(status in('online','offline','away','leave')),active_conversations integer not null default 0 check(active_conversations>=0),updated_at timestamptz not null default now());
create table public.social_conversation_assignments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,page_id uuid not null references public.facebook_pages(id) on delete cascade,external_conversation_id text not null,team_id uuid references public.social_teams(id) on delete set null,assignee_id uuid references public.profiles(id) on delete set null,status text not null default 'open' check(status in('open','waiting','resolved')),first_received_at timestamptz not null default now(),first_replied_at timestamptz,resolved_at timestamptz,last_activity_at timestamptz not null default now(),order_id uuid references public.orders(id) on delete set null,ai_assisted boolean not null default false,unique(page_id,external_conversation_id));
create index social_assignment_filters on public.social_conversation_assignments(organization_id,page_id,team_id,assignee_id,status,last_activity_at desc);
create table public.social_knowledge_entries(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,page_id uuid references public.facebook_pages(id) on delete cascade,title text not null,answer text not null,source_reply_id text,approved_by uuid not null references public.profiles(id) on delete restrict,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());

create or replace function public.can_access_social_page(target_page uuid,required_action text default 'read') returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.facebook_pages p where p.id=target_page and p.organization_id=public.current_organization_id() and (public.has_permission('social_teams.manage') or exists(select 1 from public.social_page_user_access a where a.page_id=p.id and a.user_id=auth.uid() and case required_action when 'reply' then a.can_reply when 'assign' then a.can_assign else a.can_read end) or exists(select 1 from public.social_page_teams pt join public.social_team_members tm on tm.team_id=pt.team_id and tm.user_id=auth.uid() and tm.is_active where pt.page_id=p.id))) $$;
revoke all on function public.can_access_social_page(uuid,text) from public,anon;grant execute on function public.can_access_social_page(uuid,text) to authenticated;

alter table public.social_teams enable row level security;alter table public.social_team_members enable row level security;alter table public.social_page_teams enable row level security;alter table public.social_page_user_access enable row level security;alter table public.social_agent_presence enable row level security;alter table public.social_conversation_assignments enable row level security;alter table public.social_knowledge_entries enable row level security;
create policy teams_read on public.social_teams for select to authenticated using(organization_id=public.current_organization_id() and public.has_permission('social_teams.read'));create policy teams_manage on public.social_teams for all to authenticated using(organization_id=public.current_organization_id() and public.has_permission('social_teams.manage')) with check(organization_id=public.current_organization_id() and public.has_permission('social_teams.manage'));
create policy team_members_read on public.social_team_members for select to authenticated using(exists(select 1 from public.social_teams t where t.id=team_id and t.organization_id=public.current_organization_id()) and public.has_permission('social_teams.read'));create policy team_members_manage on public.social_team_members for all to authenticated using(public.has_permission('social_teams.manage')) with check(public.has_permission('social_teams.manage'));
create policy page_teams_read on public.social_page_teams for select to authenticated using(public.can_access_social_page(page_id,'read'));create policy page_teams_manage on public.social_page_teams for all to authenticated using(public.has_permission('social_teams.manage')) with check(public.has_permission('social_teams.manage'));
create policy page_access_self_read on public.social_page_user_access for select to authenticated using(user_id=auth.uid() or public.has_permission('social_teams.manage'));create policy page_access_manage on public.social_page_user_access for all to authenticated using(public.has_permission('social_teams.manage')) with check(public.has_permission('social_teams.manage'));
create policy presence_read on public.social_agent_presence for select to authenticated using(organization_id=public.current_organization_id() and public.has_permission('social_inbox.read'));create policy presence_self_update on public.social_agent_presence for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid() and organization_id=public.current_organization_id());
create policy assignments_read on public.social_conversation_assignments for select to authenticated using(organization_id=public.current_organization_id() and public.has_permission('social_inbox.read') and public.can_access_social_page(page_id,'read'));create policy assignments_manage on public.social_conversation_assignments for all to authenticated using(organization_id=public.current_organization_id() and public.has_permission('social_inbox.assign') and public.can_access_social_page(page_id,'assign')) with check(organization_id=public.current_organization_id() and public.has_permission('social_inbox.assign') and public.can_access_social_page(page_id,'assign'));
create policy knowledge_read on public.social_knowledge_entries for select to authenticated using(organization_id=public.current_organization_id() and public.has_permission('ai_assistant.use') and (page_id is null or public.can_access_social_page(page_id,'read')));create policy knowledge_manage on public.social_knowledge_entries for all to authenticated using(organization_id=public.current_organization_id() and public.has_permission('ai_suggestions.create')) with check(organization_id=public.current_organization_id() and approved_by=auth.uid() and public.has_permission('ai_suggestions.create'));
grant select,insert,update,delete on public.social_teams,public.social_team_members,public.social_page_teams,public.social_page_user_access,public.social_agent_presence,public.social_conversation_assignments,public.social_knowledge_entries to authenticated;
insert into public.role_permissions(role_id,permission_code) select r.id,p.code from public.roles r cross join public.permissions p where r.name='Admin' and p.code in('social_teams.read','social_teams.manage','social_inbox.reassign','social_analytics.read') on conflict do nothing;
